#!/usr/bin/env node
// Writes the docs site's reference pages from the source they describe: the
// keyboard shortcuts, the CLI's help and the MCP tools agents get. `--check`
// fails when a page is out of date instead of writing it.

import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { createServer } from "vite";

const root = resolve(import.meta.dirname, "..");
const out = resolve(root, "docs-site/src/content/docs/reference");
const check = process.argv.includes("--check");
const banner =
  "{/* Generated by scripts/generate-docs-reference.mjs. Do not edit by hand. */}";

async function emit(name, contents) {
  const path = resolve(out, name);
  const actual = await readFile(path, "utf8").catch(() => null);
  if (actual === contents) return;
  if (check) throw new Error(`Docs reference page is stale: ${path}`);
  await mkdir(dirname(path), { recursive: true });
  await writeFile(path, contents);
}

const page = (title, description, body) =>
  `---\ntitle: ${JSON.stringify(title)}\ndescription: ${JSON.stringify(description)}\n---\n\n${banner}\n\n${body.trim()}\n`;

const cell = (text) =>
  String(text ?? "")
    .replaceAll("|", "\\|")
    .replaceAll("\n", " ")
    .replace(/[{}<]/g, (char) => `\\${char}`);

// The docs describe the Mac app, so the shortcuts are read as a Mac sees them.
Object.defineProperty(globalThis, "navigator", {
  value: { userAgent: "Macintosh", platform: "MacIntel" },
  configurable: true,
});
const vite = await createServer({
  root,
  logLevel: "error",
  server: { middlewareMode: true },
  appType: "custom",
});
let keybindings;
try {
  keybindings = await vite.ssrLoadModule("/src/commands/keybindings.ts");
} finally {
  await vite.close();
}

const actions = keybindings.keybindingActions();
const shortcuts = keybindings
  .keybindingCategories()
  .map((category) => {
    const rows = actions
      .filter((action) => action.category === category && action.defaultBinding)
      .map(
        (action) =>
          `| ${cell(action.label)} | \`${keybindings.keybindingLabel(action.defaultBinding)}\` | ${cell(action.detail)} |`,
      );
    if (rows.length === 0) return "";
    return `## ${category}\n\n| Action | Shortcut | What it does |\n|---|---|---|\n${rows.join("\n")}\n`;
  })
  .filter(Boolean)
  .join("\n");
await emit(
  "keyboard-shortcuts.mdx",
  page(
    "Keyboard shortcuts",
    "Every default shortcut in Sikemux on a Mac.",
    `These are the defaults. Change any of them in **Settings → Keybindings**, and search every action with the command deck (\`⌘⇧P\`).\n\n${shortcuts}`,
  ),
);

const cliSource = await readFile(
  resolve(root, "src-tauri/crates/sikemux-host/src/cli_client.rs"),
  "utf8",
);
const help = cliSource.match(/const HELP: &str = r#"([\s\S]*?)"#;/)?.[1];
if (!help)
  throw new Error(
    "could not find the CLI help in src-tauri/crates/sikemux-host/src/cli_client.rs",
  );
await emit(
  "cli.mdx",
  page(
    "CLI",
    "The sikemux command: run this host's core, open files and projects, call Sikemux's tools.",
    `On a Mac, install the \`sikemux\` command from **Settings → CLI**. On a server it comes with the core. \`sikemux help <command>\` explains each one.\n\n\`\`\`text\n${help}\`\`\`\n\nAs \`$EDITOR\`, the \`sikemux-editor\` name waits until the file is closed:\n\n\`\`\`bash\nEDITOR=sikemux-editor git commit\n\`\`\``,
  ),
);

const { tools } = JSON.parse(
  await readFile(resolve(root, "browser/tools.json"), "utf8"),
);
const groups = new Map();
for (const tool of tools) {
  const prefix = tool.name.split("_")[0];
  if (!groups.has(prefix)) groups.set(prefix, []);
  groups.get(prefix).push(`| \`${tool.name}\` | ${cell(tool.description)} |`);
}
const toolSections = [...groups]
  .map(
    ([prefix, rows]) =>
      `## ${prefix}\n\n| Tool | What it does |\n|---|---|\n${rows.join("\n")}\n`,
  )
  .join("\n");
await emit(
  "mcp-tools.mdx",
  page(
    "MCP tools",
    "The sikemux-tools MCP tools every agent in Sikemux gets.",
    `Every agent Sikemux starts gets these tools through the \`sikemux-tools\` MCP server. The same calls work from a terminal with \`sikemux tool METHOD [JSON_PARAMS]\`.\n\n${toolSections}`,
  ),
);

console.log(
  `✓ docs reference: ${actions.length} actions, ${tools.length} tools`,
);
